USE `FPS_DataCenter`;
DROP procedure IF EXISTS `SPU_SplitString`;

DELIMITER $$
USE `FPS_DataCenter`$$
CREATE PROCEDURE `SPU_SplitString` (in stringWithComma LONGTEXT)
BEGIN
	DROP TEMPORARY TABLE IF EXISTS spu_SplitString;
	CREATE TEMPORARY TABLE spu_SplitString( val LONGTEXT );
	SET @sql = concat("insert into spu_SplitString (val) values ('", REPLACE(stringWithComma, ",", "'),('"),"');");
	PREPARE stmt1 from @sql;
	EXECUTE stmt1;
	SELECT DISTINCT (val) 
		FROM spu_SplitString;
END$$

DELIMITER ;

